// Replace these clearly fictional examples only after verifying real public sources.
// No scraping or outbound contact occurs in this workflow.
const prospects = [
 { business_name:'EXAMPLE Local Shop', website:'https://example.org', verified_need:'public request for new website', source_url:'', service_fit:true, source_verified:false, buyer_contact_verified:false, do_not_contact:false },
 { business_name:'EXAMPLE Unverified Brand', website:'', verified_need:'', source_url:'', service_fit:false, source_verified:false, buyer_contact_verified:false, do_not_contact:false },
];
return prospects.map(p=>{
  const score = (p.service_fit?35:0)+(p.verified_need?30:0)+(p.source_verified?20:0)+(p.buyer_contact_verified?15:0);
  const ready = score >= 70 && p.source_verified && !p.do_not_contact;
  return {json:{...p,quality_score:score,decision:ready?'REVIEW_REQUIRED':'RESEARCH_MORE',outbound_enabled:false,reason:!p.source_verified?'Source not verified':ready?'Human approval required':'Qualification insufficient'}};
});
